CREATE TABLE "app_settings" ("id" INTEGER NOT NULL DEFAULT 1, "opening_balance" INTEGER NOT NULL, "opening_date" TEXT NOT NULL, "weekly_cap" INTEGER NOT NULL, "buffer" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "categories" ("key" TEXT NOT NULL, "label" TEXT NOT NULL, "kind" TEXT NOT NULL, "tint" TEXT NOT NULL, "is_fixed" INTEGER NOT NULL DEFAULT 0 CHECK ("is_fixed" IN (0, 1)), "monthly_budget" INTEGER NULL, "archived" INTEGER NOT NULL DEFAULT 0 CHECK ("archived" IN (0, 1)), "sort_order" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("key"));
CREATE TABLE "recurring_items" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "kind" TEXT NOT NULL, "amount" INTEGER NOT NULL CHECK("amount" > 0), "category_key" TEXT NOT NULL REFERENCES categories ("key"), "next_due" TEXT NOT NULL, "active" INTEGER NOT NULL DEFAULT 1 CHECK ("active" IN (0, 1)), "is_estimate" INTEGER NOT NULL DEFAULT 0 CHECK ("is_estimate" IN (0, 1)), "window_days" INTEGER NOT NULL DEFAULT 0 CHECK("window_days" BETWEEN 0 AND 27));
CREATE TABLE "planned_events" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "kind" TEXT NOT NULL, "amount" INTEGER NOT NULL CHECK("amount" > 0), "category_key" TEXT NOT NULL REFERENCES categories ("key"), "due_on" TEXT NOT NULL, "done" INTEGER NOT NULL DEFAULT 0 CHECK ("done" IN (0, 1)), "count_in_projection" INTEGER NOT NULL DEFAULT 1 CHECK ("count_in_projection" IN (0, 1)), "repeats_yearly" INTEGER NOT NULL DEFAULT 0 CHECK ("repeats_yearly" IN (0, 1)));
CREATE TABLE "entries" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "occurred_on" TEXT NOT NULL, "kind" TEXT NOT NULL, "amount" INTEGER NOT NULL CHECK("amount" > 0), "category_key" TEXT NOT NULL REFERENCES categories ("key"), "label" TEXT NULL, "note" TEXT NULL, "receipt" TEXT NULL, "recurring_item_id" INTEGER NULL REFERENCES recurring_items (id), "planned_event_id" INTEGER NULL REFERENCES planned_events (id), "planned_event_on" TEXT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "weekly_rules" ("weekday" INTEGER NOT NULL CHECK("weekday" BETWEEN 1 AND 7), "label" TEXT NOT NULL, "day_type" TEXT NOT NULL, "planned_spend" INTEGER NOT NULL DEFAULT 0, "is_fasting_day" INTEGER NOT NULL DEFAULT 0 CHECK ("is_fasting_day" IN (0, 1)), PRIMARY KEY ("weekday"));
CREATE TABLE "goals" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "price" INTEGER NOT NULL CHECK("price" > 0), "target_date" TEXT NOT NULL, "priority" INTEGER NOT NULL DEFAULT 1, "listing_url" TEXT NULL, "status" TEXT NOT NULL DEFAULT 'active', "achieved_on" TEXT NULL);
CREATE TABLE "favourites" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "label" TEXT NOT NULL, "category_key" TEXT NOT NULL REFERENCES categories ("key"), "amount" INTEGER NOT NULL CHECK("amount" > 0), "sort_order" INTEGER NOT NULL DEFAULT 0);
